tion class="detail" aria-label="곡 상세" hidden><h2 id="detail-title">곡 정보</h2><p id="detail-cast" class="muted"></p><div id="cast-portraits"><img id="cast-noa" src="/noa-bridge/characters/noa-face.jpg" alt="노아" hidden width="80" height="100"><img id="cast-noel" src="/noa-bridge/characters/noel-face.jpg" alt="노엘" hidden width="80" height="100"></div><button id="act-play" type="button" hidden>ACT 곡 순서대로 재생</button><h3 id="lyrics-label">가사</h3><pre id="lyrics" class="lyrics">음악을 선택하면 가사를 표시합니다.</pre></section><section class="detail" id="my-playlists" aria-label="내 플레이리스트"><h2>내 플레이리스트</h2><p id="my-status" role="status">목록을 확인하는 중입니다.</p><a id="my-login" href="/bbs/login.php?url=%2Fnoa-music.php" hidden>로그인</a><div id="my-controls" hidden><select id="my-select" aria-label="내 플레이리스트 선택"><option value="">새 플레이리스트</option></select><input id="my-title" maxlength="160" aria-label="플레이리스트 이름" placeholder="플레이리스트 이름"><div class="controls"><button id="my-new" type="button">현재 목록으로 새로 만들기</button><button id="my-add" type="button">현재 곡 담기</button><button id="my-remove" type="button">현재 곡 빼기</button><button id="my-save" type="button">목록 저장</button><button id="my-play" type="button">목록 재생</button></div></div></section><div class="filters"><input id="search" type="search" aria-label="음악 검색" placeholder="곡 제목으로 검색"><select id="type" aria-label="EP·ACT 선택"><option value="">모든 콘텐츠</option><option value="single">EP 싱글</option><option value="playlist">ACT 플레이리스트</option><option value="story">사연·커버곡</option></select><select id="genre" aria-label="장르 선택"><option value="">전체 장르</option><?php foreach($genres as $g=>$count):?><option value="<?=noa_music_e($g)?>"><?=noa_music_e(str_replace('-',' ',strtoupper($g)))?> · <?=$count?></option><?php endforeach;?></select></div><p class="muted" id="result-count"></p>
<?php if($error):?><p class="empty">음악 목록을 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.</p><?php elseif(!$songs):?><p class="empty">아직 이관된 음악이 없습니다.</p><?php endif;?>
<div class="grid" id="songs"><?php foreach($songs as $song):?><button class="song" type="button" data-key="<?=noa_music_e($song['key'])?>" data-title="<?=noa_music_e($song['title'])?>" data-genre="<?=noa_music_e($song['genre'])?>" data-video="<?=noa_music_e($song['video'])?>"><?php if($song['video']||$song['thumb']):?><img src="<?=noa_music_e($song['thumb']?:'https://i.ytimg.com/vi/'.$song['video'].'/hqdefault.jpg')?>" alt="" loading="lazy" data-stage="<?=$song['thumb']?'source':'youtube'?>" data-video="<?=noa_music_e($song['video'])?>" data-fallback="<?=noa_music_e(['female'=>'/noa-bridge/characters/noa-face.jpg','male'=>'/noa-bridge/characters/noel-face.jpg','duet'=>'/noa-bridge/characters/cast-pair.jpg'][$song['cast']]??'/noa-icon-512.png')?>" onerror="if(this.dataset.stage==='source'&amp;&amp;this.dataset.video){this.dataset.stage='youtube';this.src='https://i.ytimg.com/vi/'+this.dataset.video+'/hqdefault.jpg'}else{this.onerror=null;this.src=this.dataset.fallback}"><?php else:?><span class="cover">NOA</span><?php endif;?><div class="info"><strong><?=noa_music_e(($song['ep']?'EP.'.$song['ep'].' · ':($song['act']?'ACT.'.$song['act'].' · ':'')).$song['title'])?></strong><small><?=noa_music_e(str_replace('-',' ',strtoupper($song['genre'])))?></small><?php if($admin):?><span class="badge"><?=$song['confirmed']?'확정':'작업 중'?><?=$song['video']?'':' · 영상 링크 없음'?></span><?php endif;?></div></button><?php endforeach;?></div>
