<script>
const records=<?=json_encode($songs,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>;
const buttons=[...document.querySelectorAll('.song')],search=document.getElementById('search'),genre=document.getElementById('genre'),type=document.getElementById('type');
let browse=null,filteredQueue=[];const lookup=new Map(records.map(r=>[r.key,r]));let selected=null,player=null,ready=false,repeat=false,shuffle=false,pendingAutoplay=false,activeQueue=null;
const status=document.getElementById('player-status');
let playbackTimer=null;
function clearPlaybackWait(){if(playbackTimer!==null){clearTimeout(playbackTimer);playbackTimer=null;}}
function waitForPlayback(){clearPlaybackWait();const waitingFor=selected;status.textContent='재생을 준비하는 중입니다.';playbackTimer=setTimeout(()=>{playbackTimer=null;if(selected!==waitingFor)return;if(!ready||player.getPlayerState()!==YT.PlayerState.PLAYING)status.textContent='재생이 시작되지 않으면 영상 안의 재생 버튼을 누르거나 YouTube에서 보기를 선택해 주세요.';},12000);}
function requestPlayback(){if(!selected?.dataset.video)return;pendingAutoplay=true;waitForPlayback();if(ready)player.playVideo();else if(window.YT?.Player)createPlayer();}

function queue(){const playable=filteredQueue.filter(b=>b.dataset.video);if(activeQueue)return playable;const playlist=selected&&lookup.get(selected.dataset.key)?.kind==='playlist',sameKind=playable.filter(b=>(lookup.get(b.dataset.key)?.kind==='playlist')===!!playlist);return sameKind.length?sameKind:playable;}
function filter(){
 const q=search.value.trim().toLocaleLowerCase();let rows=records.filter(r=>!((activeQueue&&!activeQueue.includes(r.key))||(type.value&&r.kind!==type.value)||(genre.value&&r.genre!==genre.value)||(q&&!(r.title+' EP.'+r.ep+' ACT.'+r.act).toLocaleLowerCase().includes(q))));
 if(activeQueue)rows.sort((a,b)=>activeQueue.indexOf(a.key)-activeQueue.indexOf(b.key));
 const view=browse?browse.apply(rows,!!activeQueue):{visible:rows,queue:rows,stage:'songs'},visible=new Set(view.visible.map(r=>r.key));
 filteredQueue=view.queue.map(r=>buttons.find(b=>b.dataset.key===r.key)).filter(Boolean);
 buttons.forEach(b=>{b.hidden=!visible.has(b.dataset.key);b.style.order=activeQueue?String(activeQueue.indexOf(b.dataset.key)):'';});
 document.getElementById('songs').hidden=view.stage!=='songs';document.getElementById('result-count').textContent=view.stage==='songs'?view.queue.length+'개 항목 · 재생 대기열 '+queue().length+'개':'';
}
function resetQueue(){activeQueue=null;filter()}search.addEventListener('input',resetQueue);genre.addEventListener('change',resetQueue);type.addEventListener('change',resetQueue);const params=new URLSearchParams(location.search);if([...genre.options].some(o=>o.value===params.get('genre')))genre.value=params.get('genre');if([...type.options].some(o=>o.value===params.get('type')))type.value=params.get('type');filter();
function select(b,autoplay){
 if(selected===b&&ready){if(autoplay)requestPlayback();return;}
 clearPlaybackWait();
 selected=b;pendingAutoplay=autoplay;const r=lookup.get(b.dataset.key);document.querySelector('.player').hidden=false;document.querySelector('.noa-transport').hidden=false;document.querySelector('[aria-label="곡 상세"]').hidden=false;if(browse)filter();buttons.forEach(x=>x.classList.toggle('selected',x===b));
 document.getElementById('now-title').textContent=r.title;document.getElementById('dock-title').textContent=r.title;document.getElementById('now-genre').textContent=r.genre.replaceAll('-',' ').toUpperCase();
 document.getElementById('detail-title').textContent=(r.ep?'EP.'+r.ep+' · ':r.act?'ACT.'+r.act+' · ':'')+r.title;
 document.getElementById('detail-cast').textContent=({female:'노아 · 여성 솔로',male:'노엘 · 남성 솔로',duet:'노아 & 노엘 · 남녀 듀엣'})[r.cast]||'캐릭터 정보 미등록';
 document.getElementById('cast-noa').hidden=!['female','duet'].includes(r.cast);document.getElementById('cast-noel').hidden=!['male','duet'].includes(r.cast);
 document.getElementById('lyrics-label').textContent=r.kind==='playlist'?'ACT 곡 구성':'가사';document.getElementById('lyrics').textContent=(r.kind==='playlist'?r.tracklist:r.lyrics)||'등록된 내용이 없습니다.';
 const members=r.kind==='playlist'?[...r.tracklist.matchAll(/^\s*(?:[0-9]{1,2}:[0-9]{2}(?::[0-9]{2})?\s+)?EP[.\s]*([0-9]{1,3})\b/gm)].map(m=>'single:'+r.genre+':'+m[1].padStart(2,'0')):[];const ordered=[...new Set(members)].filter(key=>lookup.has(key));const actButton=document.getElementById('act-play');actButton.hidden=ordered.length===0;actButton.onclick=()=>{activeQueue=ordered;genre.value=r.genre;type.value='single';search.value='';filter();const first=queue()[0];if(first)select(first,true)};
 const watch=document.getElementById('watch');watch.hidden=!r.video;if(r.video)watch.href='https://www.youtube.com/watch?v='+r.video;
 status.textContent=r.video?'':'등록된 재생 주소가 없습니다. 곡 정보와 가사를 확인할 수 있습니다.';
 if(!r.video){if(ready)player.stopVideo();return;}
 try{sessionStorage.setItem('noa-last-song',r.key)}catch{}
 if(autoplay)waitForPlayback();
 if(ready){const command=autoplay?'loadVideoById':'cueVideoById';player[command](r.video)}else if(window.YT?.Player)createPlayer();
}
function move(direction,ended=false){const q=queue();if(!q.length)return;let i=q.indexOf(selected);if(ended&&repeat&&selected?.dataset.video){select(selected,true);return}if(shuffle&&q.length>1){const other=q.filter(b=>b!==selected);select(other[Math.floor(Math.random()*other.length)],true);return}if(i<0)i=direction>0?-1:0;let n=i+direction;if(ended&&n>=q.length)return;select(q[(n+q.length)%q.length],true)}
function createPlayer(){if(player||!selected?.dataset.video)return;const mount=document.createElement('div');mount.id='youtube-player';document.getElementById('screen').replaceChildren(mount);player=new YT.Player('youtube-player',{host:'https://www.youtube-nocookie.com',videoId:selected.dataset.video,playerVars:{playsinline:1,origin:location.origin,rel:0},events:{onReady:e=>{ready=true;e.target.setVolume(Number(document.getElementById('volume').value));if(pendingAutoplay)waitForPlayback();if(selected?.dataset.video){e.target[pendingAutoplay?'loadVideoById':'cueVideoById']({videoId:selected.dataset.video,startSeconds:restorePosition(selected.dataset.key)})}else e.target.stopVideo()},onStateChange:e=>{if([YT.PlayerState.PLAYING,YT.PlayerState.PAUSED,YT.PlayerState.ENDED].includes(e.data))clearPlaybackWait();document.getElementById('pause-play').innerHTML='<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="'+(e.data===YT.PlayerState.PLAYING?'M8 5v14M16 5v14':'m8 5 11 7-11 7V5Z')+'"/></svg>';document.getElementById('pause-play').setAttribute('aria-pressed',String(e.data===YT.PlayerState.PLAYING));if(e.data===YT.PlayerState.ENDED)move(1,true);if(e.data===YT.PlayerState.PLAYING)status.textContent='재생 중';if(e.data===YT.PlayerState.BUFFERING)status.textContent='재생을 준비하는 중입니다.';if(e.data===YT.PlayerState.PAUSED)status.textContent='일시정지';},onError:()=>{clearPlaybackWait();status.textContent='이 영상은 현재 재생할 수 없습니다. 공개 상태 또는 YouTube 재생 제한을 확인해 주세요.'},onAutoplayBlocked:()=>{clearPlaybackWait();status.textContent='플레이어의 재생 버튼을 눌러 주세요.'}}});}
function restorePosition(key){try{const p=JSON.parse(sessionStorage.getItem('noa-playback-position')||'null');return p?.key===key&&Number.isFinite(p.seconds)?Math.max(0,p.seconds):0}catch{return 0}}
document.getElementById('dock-more').onclick=e=>{const bar=document.querySelector('.noa-transport');const expanded=bar.dataset.expanded!=='true';bar.dataset.expanded=String(expanded);e.currentTarget.setAttribute('aria-expanded',String(expanded));};
document.getElementById('pause-play').onclick=()=>{if(ready&&player.getPlayerState()===YT.PlayerState.PLAYING){pendingAutoplay=false;clearPlaybackWait();player.pauseVideo();}else requestPlayback();};
document.getElementById('seek').oninput=e=>{if(ready&&player.getDuration()>0)player.seekTo(player.getDuration()*Number(e.target.value)/1000,true)};
document.getElementById('volume').oninput=e=>{if(ready)player.setVolume(Number(e.target.value))};
const clock=s=>Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');setInterval(()=>{if(!ready||!selected)return;const seconds=player.getCurrentTime(),duration=player.getDuration();if(duration>0){document.getElementById('seek').value=String(Math.round(1000*seconds/duration));document.getElementById('seek-clock').textContent=clock(seconds)+' / '+clock(duration)}try{if(seconds>0)sessionStorage.setItem('noa-playback-position',JSON.stringify({key:selected.dataset.key,seconds}))}catch{}},1000);
window.onYouTubeIframeAPIReady=createPlayer;window.addEventListener('noa-background',()=>{pendingAutoplay=false;clearPlaybackWait();if(ready)player.pauseVideo()});
buttons.forEach(b=>b.addEventListener('click',()=>select(b,true)));document.getElementById('previous').onclick=()=>move(-1);document.getElementById('next').onclick=()=>move(1);
for(const id of ['repeat','shuffle'])document.getElementById(id).onclick=e=>{if(id==='repeat')repeat=!repeat;else shuffle=!shuffle;e.currentTarget.setAttribute('aria-pressed',String(id==='repeat'?repeat:shuffle))};
let saved='';try{saved=sessionStorage.getItem('noa-last-song')||''}catch{}const first=buttons.find(b=>b.dataset.key===new URLSearchParams(location.search).get('track'))||buttons.find(b=>b.dataset.key===saved&&!b.hidden);if(first)select(first,false);
window.addEventListener('DOMContentLoaded',()=>{browse=window.NoaBrowse.mount({host:document.getElementById('music-browse'),rows:records,onChange:filter,search,genre,type});if(first)browse.reveal(lookup.get(first.dataset.key));filter();const personal=document.getElementById('my-playlists');const showPersonal=()=>personal.hidden=location.hash!=='#my-playlists';showPersonal();window.addEventListener('hashchange',showPersonal);});
const api=document.createElement('script');api.src='https://www.youtube.com/iframe_api';api.onerror=()=>{status.textContent='플레이어를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.'};document.head.append(api);
if('serviceWorker' in navigator)navigator.serviceWorker.register('/noa-sw.js').catch(()=>{});
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.getElementById('install').hidden=false});document.getElementById('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;document.getElementById('install').hidden=true}};
</script><script src="/noa-playlists.js" defer></script></main></body></html>
